<?php
require_once __DIR__.'/../config/bootstrap.php';require_admin();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM customers WHERE id=?');$s->execute([$id]);$customer=$s->fetch();if(!$customer){http_response_code(404);exit('Customer not found');}
$s=db()->prepare('SELECT id,order_number,grand_total,order_status,created_at FROM orders WHERE customer_id=? ORDER BY id DESC LIMIT 100');$s->execute([$id]);$orders=$s->fetchAll();
$pageTitle='Customer details — Ikki';require __DIR__.'/../includes/header.php';?>
<div class="admin-shell"><h1 class="page-title"><?=e($customer['full_name'])?></h1><nav class="admin-nav"><a href="/admin/">Overview</a><a href="/admin/customers.php">Customers</a><a href="/admin/orders.php">Orders</a></nav>
<div class="stats"><div class="stat"><span class="muted">Phone</span><b style="font-size:20px"><?=e($customer['phone'])?></b></div><div class="stat"><span class="muted">WhatsApp</span><b style="font-size:20px"><?=e($customer['whatsapp_phone']??'—')?></b></div><div class="stat"><span class="muted">Email</span><b style="font-size:18px"><?=e($customer['email']??'—')?></b></div><div class="stat"><span class="muted">Customer since</span><b style="font-size:18px"><?=e($customer['created_at'])?></b></div></div>
<h2 style="font:32px var(--serif);margin-top:40px">Order history</h2><div style="overflow-x:auto"><table class="cart-table"><thead><tr><th>Order</th><th>Total</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=e($o['order_number'])?></td><td><?=money($o['grand_total'])?></td><td><?=e($o['order_status'])?></td><td><?=e($o['created_at'])?></td><td><a href="/admin/order.php?id=<?=(int)$o['id']?>">Details</a></td></tr><?php endforeach;?><?php if(!$orders):?><tr><td colspan="5">No orders recorded for this customer.</td></tr><?php endif;?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php';?>